module iir3_v9 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] y2;
  wire [31:0] fxp16 = $shortrealtobits((37*$bitstoshortreal(x)) + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; y2<=0; r1<=0; r2<=0; r3<=0; end
    else begin
      y <= fxp16;
      y2 <= y;
      r1 <= (62*$bitstoshortreal(x) + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF;
      r2 <= (53*$bitstoshortreal(x) + (62*$bitstoshortreal(x) + ((9*y)>>4) + ((5*y2)>>4))) & 16'hFFFF;
      r3 <= (36*$bitstoshortreal(x) + (53*$bitstoshortreal(x) + (62*$bitstoshortreal(x) + ((9*y)>>4) + ((5*y2)>>4)))) & 16'hFFFF;
    end
  end
endmodule

